// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

// Load Google Font at module level
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type CTONodeSlamProps = Record<string, any>;

const CTONodeSlam: React.FC<CTONodeSlamProps> = ({
  backgroundColor = "#040814",
  transparentBackground = false,
  durationInSeconds = 6,
  wallColor = "#b41e1e",
  nodeColor = "#0d47a1",
  glowColor = "#00f0ff",
  impactIntensity = 5,
  particleCount = 60,
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  // Clean background configuration
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Chart coordinate definition
  const points = [
    { x: width * 0.05, y: height * 0.88 },
    { x: width * 0.16, y: height * 0.81 },
    { x: width * 0.26, y: height * 0.76 },
    { x: width * 0.36, y: height * 0.69 },
    { x: width * 0.46, y: height * 0.56 },
    { x: width * 0.58, y: height * 0.38 }, // Impact Point
  ];

  const p4 = points[4];
  const p5 = points[5];

  // Piecewise motion tracker function for the traveling CTO node
  const getPosAtFrame = (f: number) => {
    if (f <= 15) return points[0];
    if (f >= 50) {
      // Post-impact shake and slight rebound
      const t = f - 50;
      const shakeX = Math.sin(t * 1.5) * Math.max(0, (impactIntensity * 3) - t * 0.6);
      const shakeY = Math.cos(t * 1.5) * Math.max(0, (impactIntensity * 2) - t * 0.4);
      const rebound = Math.max(0, 12 - t * 0.5);
      return { x: p5.x - rebound + shakeX, y: p5.y + shakeY };
    }

    // Linearly interpolate through active segment
    const totalTravelFrames = 35; // from frame 15 to 50
    const segDuration = totalTravelFrames / 5; // 7 frames per segment
    const segmentIndex = Math.min(4, Math.floor((f - 15) / segDuration));
    const segmentProgress = ((f - 15) % segDuration) / segDuration;

    const startPt = points[segmentIndex];
    const endPt = points[segmentIndex + 1];

    return {
      x: startPt.x + (endPt.x - startPt.x) * segmentProgress,
      y: startPt.y + (endPt.y - startPt.y) * segmentProgress,
    };
  };

  const currentPos = getPosAtFrame(frame);

  // Dynamic values for Node Scale
  const nodeScale = interpolate(frame, [15, 22], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const nodeSize = Math.min(width, height) * 0.12;

  // Brick Configuration
  const brickWidth = 80;
  const brickHeight = 36;
  const wallStartX = width * 0.58;
  const cols = Math.ceil((width * 0.45) / brickWidth) + 1;
  const rows = Math.ceil(height / brickHeight) + 1;

  // Pre-generate deterministic particles on impact (frame >= 50)
  const particles = React.useMemo(() => {
    return Array.from({ length: particleCount }).map((_, i) => {
      // Explode outwards rightwards (from -PI/3 to PI/3 angle)
      const angle = (random(`p-angle-${i}`) * Math.PI / 1.5) - Math.PI / 3;
      const speed = random(`p-speed-${i}`) * 20 + 5;
      const size = random(`p-size-${i}`) * 12 + 6;
      const isBlue = random(`p-color-${i}`) > 0.45;
      const rotSpeed = (random(`p-rot-${i}`) - 0.5) * 15;
      return { angle, speed, size, isBlue, rotSpeed };
    });
  }, [particleCount]);

  // Render brick dynamic layout
  const bricksRender = React.useMemo(() => {
    return Array.from({ length: rows }).map((_, r) => {
      return Array.from({ length: cols }).map((_, c) => {
        const baseX = c * brickWidth + (r % 2 === 0 ? brickWidth / 2 : 0);
        const baseY = r * brickHeight;
        const absX = wallStartX + baseX;
        const absY = baseY;

        let dx = 0;
        let dy = 0;
        let rot = 0;
        let colorFactor = 0;

        if (frame >= 50) {
          const t = frame - 50;
          const dist = Math.sqrt((absX - p5.x) ** 2 + (absY - p5.y) ** 2);
          if (dist < 220) {
            // Apply impact force based on proximity
            const force = interpolate(
              t,
              [0, 15],
              [0, Math.max(0, (220 - dist) * 0.55 * (impactIntensity / 5))],
              { extrapolateRight: "clamp" }
            );
            const angle = Math.atan2(absY - p5.y, absX - p5.x);
            dx = Math.cos(angle) * force;
            dy = Math.sin(angle) * force + (t * t * 0.05); // Gravity effect
            rot = (random(`brick-rot-${r}-${c}`) - 0.5) * force * 1.8;

            const colorT = interpolate(t, [0, 8, 40], [0, 1, 0], {
              extrapolateRight: "clamp",
            });
            colorFactor = Math.max(0, (220 - dist) / 220) * colorT;
          }
        }

        const opacity = 0.55 + 0.45 * colorFactor;
        const r_val = Math.round(180 + (255 - 180) * colorFactor);
        const g_val = Math.round(30 + (100 - 30) * colorFactor);
        const b_val = Math.round(30 + (50 - 30) * colorFactor);
        const fill = `rgba(${r_val}, ${g_val}, ${b_val}, ${opacity})`;

        return (
          <rect
            key={`${r}-${c}`}
            x={baseX}
            y={baseY}
            width={brickWidth - 3}
            height={brickHeight - 3}
            fill={fill}
            stroke="rgba(0,0,0,0.25)"
            strokeWidth={1}
            style={{
              transform: `translate(${dx}px, ${dy}px) rotate(${rot}deg)`,
              transformOrigin: `${baseX + brickWidth / 2}px ${baseY + brickHeight / 2}px`,
              transition: "none",
            }}
          />
        );
      });
    });
  }, [frame, rows, cols, p5.x, p5.y, impactIntensity]);

  // Main growth line drawing interpolation
  const lineDrawProgress = interpolate(frame, [0, 35], [1100, 0], {
    extrapolateRight: "clamp",
  });

  // Calculate the SVG path for the line (Shortens at frame 50 to represent shatter)
  const linePath = frame >= 50
    ? `M ${points[0].x} ${points[0].y} L ${points[1].x} ${points[1].y} L ${points[2].x} ${points[2].y} L ${points[3].x} ${points[3].y} L ${p4.x} ${p4.y}`
    : `M ${points[0].x} ${points[0].y} L ${points[1].x} ${points[1].y} L ${points[2].x} ${points[2].y} L ${points[3].x} ${points[3].y} L ${p4.x} ${p4.y} L ${p5.x} ${p5.y}`;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Sleek dashboard system diagnostics header */}
      <div
        style={{
          position: "absolute",
          left: width * 0.05,
          top: height * 0.08,
          fontFamily: spaceGroteskFamily,
          color: "white",
          zIndex: 2,
          transition: "none",
        }}
      >
        <div
          style={{
            fontSize: 26,
            fontWeight: 800,
            letterSpacing: 2,
            color: glowColor,
            textShadow: `0 0 10px ${glowColor}55`,
            marginBottom: 4,
          }}
        >
          SCALING BARRIER DIAGNOSTIC
        </div>
        <div
          style={{
            fontSize: 14,
            color: "rgba(255, 255, 255, 0.5)",
            letterSpacing: 1,
          }}
        >
          METRIC: CTO EFFICIENCY VS. ARCHITECTURAL LIMITS
        </div>
      </div>

      {/* Grid line background */}
      {points.map((pt, idx) => (
        <div
          key={`grid-${idx}`}
          style={{
            position: "absolute",
            left: width * 0.05,
            top: pt.y,
            width: width * 0.53,
            height: 1,
            borderTop: "1px dashed rgba(255, 255, 255, 0.08)",
            transition: "none",
          }}
        />
      ))}

      {/* Static Axes */}
      <div
        style={{
          position: "absolute",
          left: width * 0.05,
          top: height * 0.35,
          width: 2,
          height: height * 0.53,
          backgroundColor: "rgba(255, 255, 255, 0.2)",
          transition: "none",
        }}
      />
      <div
        style={{
          position: "absolute",
          left: width * 0.05,
          top: height * 0.88,
          width: width * 0.53,
          height: 2,
          backgroundColor: "rgba(255, 255, 255, 0.2)",
          transition: "none",
        }}
      />

      {/* Growth Path Vector and static/glow nodes */}
      <svg
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          width: width,
          height: height,
          pointerEvents: "none",
        }}
      >
        <defs>
          <linearGradient id="glowGrad" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#0072ff" />
            <stop offset="100%" stopColor={glowColor} />
          </linearGradient>
          <filter id="neonGlow">
            <feGaussianBlur stdDeviation="6" result="coloredBlur" />
            <feMerge>
              <feMergeNode in="coloredBlur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>

        <path
          d={linePath}
          fill="none"
          stroke="url(#glowGrad)"
          strokeWidth="6"
          strokeLinecap="round"
          strokeDasharray="1100"
          strokeDashoffset={lineDrawProgress}
          filter="url(#neonGlow)"
        />
      </svg>

      {/* Static Point nodes (representing stable milestone achievements) */}
      {points.map((pt, idx) => {
        if (idx === 5) return null; // Destructible point
        const ptScale = interpolate(frame, [idx * 6, idx * 6 + 10], [0, 1], {
          extrapolateRight: "clamp",
        });
        return (
          <div
            key={`node-${idx}`}
            style={{
              position: "absolute",
              left: pt.x - 7,
              top: pt.y - 7,
              width: 14,
              height: 14,
              borderRadius: "50%",
              backgroundColor: glowColor,
              boxShadow: `0 0 10px ${glowColor}`,
              transform: `scale(${ptScale})`,
              transition: "none",
              zIndex: 3,
            }}
          />
        );
      })}

      {/* Dynamic Brick Wall */}
      <div
        style={{
          position: "absolute",
          left: wallStartX,
          top: 0,
          width: width * 0.42,
          height: height,
          backgroundColor: "rgba(10, 5, 5, 0.65)",
          borderLeft: "2px solid rgba(255, 50, 50, 0.3)",
          overflow: "visible",
          transition: "none",
        }}
      >
        <svg
          style={{
            width: "100%",
            height: "100%",
            overflow: "visible",
          }}
        >
          {bricksRender}
        </svg>
      </div>

      {/* Impact Shockwave and Fracture Overlays */}
      {frame >= 50 && (
        <>
          {/* Neon Impact Ripple */}
          <div
            style={{
              position: "absolute",
              left: p5.x - interpolate(frame, [50, 75], [0, 260], { extrapolateRight: "clamp" }) / 2,
              top: p5.y - interpolate(frame, [50, 75], [0, 260], { extrapolateRight: "clamp" }) / 2,
              width: interpolate(frame, [50, 75], [0, 260], { extrapolateRight: "clamp" }),
              height: interpolate(frame, [50, 75], [0, 260], { extrapolateRight: "clamp" }),
              borderRadius: "50%",
              border: `4px solid ${glowColor}`,
              boxShadow: `0 0 15px ${glowColor}`,
              opacity: interpolate(frame, [50, 75], [0.9, 0], { extrapolateRight: "clamp" }),
              transition: "none",
              pointerEvents: "none",
              zIndex: 6,
            }}
          />
          <div
            style={{
              position: "absolute",
              left: p5.x - interpolate(frame, [50, 70], [0, 180], { extrapolateRight: "clamp" }) / 2,
              top: p5.y - interpolate(frame, [50, 70], [0, 180], { extrapolateRight: "clamp" }) / 2,
              width: interpolate(frame, [50, 70], [0, 180], { extrapolateRight: "clamp" }),
              height: interpolate(frame, [50, 70], [0, 180], { extrapolateRight: "clamp" }),
              borderRadius: "50%",
              border: `5px solid #ff3b30`,
              boxShadow: `0 0 20px #ff3b30`,
              opacity: interpolate(frame, [50, 70], [1, 0], { extrapolateRight: "clamp" }),
              transition: "none",
              pointerEvents: "none",
              zIndex: 6,
            }}
          />

          {/* SVG Crack overlays */}
          <svg
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              width: width,
              height: height,
              pointerEvents: "none",
              zIndex: 4,
            }}
          >
            <path
              d={`M ${p5.x} ${p5.y} L ${p5.x + 55} ${p5.y - 45} L ${p5.x + 110} ${p5.y - 30}`}
              stroke="#ff4d4d"
              strokeWidth="4"
              fill="none"
              opacity={interpolate(frame, [50, 85], [1, 0], { extrapolateRight: "clamp" })}
            />
            <path
              d={`M ${p5.x} ${p5.y} L ${p5.x + 65} ${p5.y + 55} L ${p5.x + 140} ${p5.y + 40}`}
              stroke="#ff4d4d"
              strokeWidth="5"
              fill="none"
              opacity={interpolate(frame, [50, 85], [1, 0], { extrapolateRight: "clamp" })}
            />
            <path
              d={`M ${p5.x} ${p5.y} L ${p5.x + 30} ${p5.y - 85} L ${p5.x + 45} ${p5.y - 150}`}
              stroke="#ff4d4d"
              strokeWidth="3"
              fill="none"
              opacity={interpolate(frame, [50, 85], [1, 0], { extrapolateRight: "clamp" })}
            />
          </svg>
        </>
      )}

      {/* Shattered Growth Line Fragment Animations (falling down) */}
      {frame >= 50 && (
        <svg
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: width,
            height: height,
            pointerEvents: "none",
            zIndex: 4,
          }}
        >
          {/* Shattered segments */}
          <g
            style={{
              transform: `translate(${(frame - 50) * 1.5}px, ${(frame - 50) ** 2 * 0.12}px) rotate(${(frame - 50) * 2.5}deg)`,
              transformOrigin: `${(p4.x + p5.x) / 2}px ${(p4.y + p5.y) / 2}px`,
            }}
          >
            <line
              x1={p4.x}
              y1={p4.y}
              x2={p4.x + (p5.x - p4.x) * 0.4}
              y2={p4.y + (p5.y - p4.y) * 0.4}
              stroke={glowColor}
              strokeWidth="5"
              strokeLinecap="round"
              opacity={interpolate(frame, [50, 75], [1, 0], { extrapolateRight: "clamp" })}
            />
          </g>
          <g
            style={{
              transform: `translate(${(frame - 50) * 3}px, ${(frame - 50) ** 2 * 0.15}px) rotate(${(frame - 50) * -3}deg)`,
              transformOrigin: `${(p4.x + p5.x) / 2}px ${(p4.y + p5.y) / 2}px`,
            }}
          >
            <line
              x1={p4.x + (p5.x - p4.x) * 0.5}
              y1={p4.y + (p5.y - p4.y) * 0.5}
              x2={p5.x}
              y2={p5.y}
              stroke={glowColor}
              strokeWidth="5"
              strokeLinecap="round"
              opacity={interpolate(frame, [50, 70], [1, 0], { extrapolateRight: "clamp" })}
            />
          </g>
        </svg>
      )}

      {/* Dynamic Digital Data Shard / Particle Burst */}
      {frame >= 50 &&
        particles.map((p, i) => {
          const t = frame - 50;
          const x = p5.x + Math.cos(p.angle) * p.speed * t;
          const y = p5.y + Math.sin(p.angle) * p.speed * t + 0.13 * t * t; // Acceleration by gravity
          const rot = p.rotSpeed * t;
          const opacity = interpolate(t, [15, 35], [1, 0], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          const size = p.size * interpolate(t, [0, 35], [1, 0.15], { extrapolateRight: "clamp" });

          if (opacity <= 0) return null;

          return (
            <div
              key={`particle-${i}`}
              style={{
                position: "absolute",
                left: x - size / 2,
                top: y - size / 2,
                width: size,
                height: size,
                backgroundColor: p.isBlue ? glowColor : "#ff3b30",
                boxShadow: `0 0 10px ${p.isBlue ? glowColor : "#ff3b30"}`,
                transform: `rotate(${rot}deg)`,
                opacity,
                transition: "none",
                clipPath: i % 3 === 0 ? "polygon(50% 0%, 0% 100%, 100% 100%)" : "none", // Triangle / Square shards mix
                zIndex: 8,
              }}
            />
          );
        })}

      {/* Motion Trail (Active during climbing segment: frame 15 - 50) */}
      {frame > 15 && frame < 55 && (
        <>
          {[1.5, 3, 4.5].map((delay, index) => {
            const trailPos = getPosAtFrame(frame - delay);
            const trailScale = nodeScale * (1 - delay * 0.08);
            const trailOpacity = 0.5 * (1 - delay * 0.15);

            if (frame - delay < 15) return null;

            return (
              <div
                key={`trail-${index}`}
                style={{
                  position: "absolute",
                  left: trailPos.x - nodeSize / 2,
                  top: trailPos.y - nodeSize / 2,
                  width: nodeSize,
                  height: nodeSize,
                  borderRadius: "50%",
                  border: `${Math.min(width, height) * 0.005}px solid ${glowColor}`,
                  boxShadow: `0 0 12px ${glowColor}`,
                  backgroundColor: "transparent",
                  transform: `scale(${trailScale})`,
                  opacity: trailOpacity,
                  pointerEvents: "none",
                  zIndex: 8,
                  transition: "none",
                }}
              />
            );
          })}
        </>
      )}

      {/* Main Glowing CTO Node Container */}
      <div
        style={{
          position: "absolute",
          left: currentPos.x - nodeSize / 2,
          top: currentPos.y - nodeSize / 2,
          width: nodeSize,
          height: nodeSize,
          borderRadius: "50%",
          backgroundColor: nodeColor,
          border: `${Math.min(width, height) * 0.008}px solid ${glowColor}`,
          boxShadow: `0 0 20px ${glowColor}, inset 0 0 15px ${glowColor}aa`,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          transform: `scale(${nodeScale})`,
          zIndex: 10,
          transition: "none",
        }}
      >
        <svg
          viewBox="0 0 40 40"
          style={{
            width: nodeSize * 0.42,
            height: nodeSize * 0.42,
            marginBottom: 2,
            filter: `drop-shadow(0 0 6px ${glowColor})`,
          }}
        >
          <path
            d="M20 15c2.76 0 5-2.24 5-5s-2.24-5-5-5-5 2.24-5 5 2.24 5 5 5zm0 3c-4.42 0-13 2.24-13 6.67V28h26v-3.33c0-4.43-8.58-6.67-13-6.67z"
            fill="white"
          />
        </svg>
        <div
          style={{
            color: "white",
            fontSize: nodeSize * 0.22,
            fontWeight: "bold",
            fontFamily: spaceGroteskFamily,
            letterSpacing: 1,
            textShadow: `0 0 8px ${glowColor}`,
          }}
        >
          CTO
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default CTONodeSlam;